Function message <- StockFromLine(line As String)
  Define message As String;
  Define cut As Integer <- -1;
  For position <- 0 To length(line) - 1 Do
    If substring(line, position, position) = ";" Then
      cut <- position;
    EndIf
  EndFor
  If cut = -1 Then
    message <- "Invalid line";
  Else
    message <- substring(line, 0, cut - 1) + " has " + substring(line, cut + 1, length(line) - 1);
  EndIf
EndFunction

